"""v1.25.0 README 更新 —— 迭代记录 + 核心特性 + 目录结构 + 使用方式。

注意：README 的换行符原样保留（脚本按文件里实际用的换行符转换插入内容）。
"""
import io
import os

ROOT = r"Z:/【01】自研软件/【26-19】本地影视中心"
README = os.path.join(ROOT, "README.md")


def patch_file(path, label, old, new, count=1):
    s = io.open(path, encoding="utf-8", newline="").read()
    nl = "\r\n" if "\r\n" in s else "\n"
    old = old.replace("\n", nl)
    new = new.replace("\n", nl)
    got = s.count(old)
    if got != count:
        raise SystemExit(f"[ABORT] {label}: 锚点命中 {got} 次（期望 {count}）\n---\n{old[:400]}")
    with io.open(path, "w", encoding="utf-8", newline="") as f:
        f.write(s.replace(old, new, count))
    print(f"[OK] {label}")


